sk_string sk_string_char_at(sk_string s, sk_int idx) {
    if (s.__is_null || idx.__is_null) return SK_NULL_string;
    const char* p = s.value;
    int i = 0;
    while (*p && i < idx.value) {
        int l = 0;
        __sk__utf8__decode(p, &l);
        p += l;
        i++;
    }
    if (!*p) return SK_NULL_string;
    int l = 0;
    __sk__utf8__decode(p, &l);
    char* buf = malloc(l + 1);
    memcpy(buf, p, l);
    buf[l] = '\0';
    return sk_string_new_take(buf);
}


