void sk_array_push_string(sk_array* a, sk_string v) { sk_string copy = v.__is_null ? SK_NULL_string : sk_string_new(v.value); sk_array_push(a, &copy); }
void sk_array_push_float(sk_array* a, sk_float v) { sk_array_push(a, &v); }
void sk_array_push_double(sk_array* a, sk_double v) { sk_array_push(a, &v); }
void sk_array_push_bool(sk_array* a, sk_bool v) { sk_array_push(a, &v); }
void sk_array_push_any(sk_array* a, sk_any v) { sk_any copy = v; if (v.type == 1 && v.data.s) copy.data.s = strdup(v.data.s); else if (v.type == 5 && v.data.p) copy.data.p = sk_array_deep_copy((sk_array*)v.data.p); sk_array_push(a, &copy); }
void sk_array_push_arr(sk_array* a, sk_arr v) { sk_arr copy = v.__is_null ? SK_NULL_arr : sk_arr_new(sk_array_deep_copy(v.value)); sk_array_push(a, &copy); }

void* sk_array_get(sk_array* a, int index) {
    if (index < 0 || index >= a->length) return NULL;
    return (char*)a->data + index * a->elem_size;
}

int sk_array_len(sk_array* a) { return a->length; }

sk_array* sk_array_copy(sk_array* a) {
    sk_array* new = sk_array_new(a->elem_size, a->elem_type);
    for (int i = 0; i < a->length; i++) {
        sk_array_push(new, sk_array_get(a, i));
    }
    return new;
}

void sk_array_free(sk_array* a) {
    free(a->data);
    free(a);
}

sk_array* sk_range_new(int start, int end) {
    sk_array* a = sk_array_new(sizeof(sk_int), 0);
    if (start <= end) {
        for (int i = start; i <= end; i++) {
            sk_int v = sk_int_new(i);
            sk_array_push_int(a, v);
        }
    } else {
        for (int i = start; i >= end; i--) {
            sk_int v = sk_int_new(i);
            sk_array_push_int(a, v);
        }
    }
    return a;
}

// FNV-1a 32-bit
static unsigned int __sk__dict_hash(const char* s) {
    unsigned int h = 2166136261u;
    while (*s) { h ^= (unsigned char)*s++; h *= 16777619u; }
    return h;
}

sk_dict* sk_dict_new(void) {
    sk_dict* d = malloc(sizeof(sk_dict));
    d->capacity = 0;
    d->length = 0;
    d->entries = NULL;
    return d;
}

static void __sk__dict_ensure_capacity(sk_dict* d) {
    if (d->capacity > 0) return;
    d->capacity = 16;
    d->entries = calloc(d->capacity, sizeof(sk_dict_entry));
}

// Ищет слот для ключа. Возвращает либо индекс найденного, либо индекс первого свободного.
static int __sk__dict_find(sk_dict* d, const char* key, unsigned int h) {
    unsigned int i = h % (unsigned int)d->capacity;
    while (d->entries[i].key != NULL) {
        if (strcmp(d->entries[i].key, key) == 0) return (int)i;
        i = (i + 1) % (unsigned int)d->capacity;
    }
    return (int)i;
}

static void __sk__dict_grow(sk_dict* d) {
    int old_cap = d->capacity;
    sk_dict_entry* old = d->entries;
    d->capacity = old_cap * 2;
    d->entries = calloc(d->capacity, sizeof(sk_dict_entry));
    for (int i = 0; i < old_cap; i++) {
        if (old[i].key != NULL) {
            int slot = __sk__dict_find(d, old[i].key, __sk__dict_hash(old[i].key));
            d->entries[slot] = old[i];
        }
    }
    free(old);
}

void sk_dict_set(sk_dict* d, sk_string key, sk_any value) {
    if (key.__is_null) return;
    __sk__dict_ensure_capacity(d);
    unsigned int h = __sk__dict_hash(key.value);
    int slot = __sk__dict_find(d, key.value, h);
    if (d->entries[slot].key != NULL) {
        sk_any_free(&d->entries[slot].value);
        d->entries[slot].value = value;
        return;
    }
    d->entries[slot].key = strdup(key.value);
    d->entries[slot].value = value;
    d->length++;
    if (d->length * 4 >= d->capacity * 3)
        __sk__dict_grow(d);
}

sk_any sk_dict_get(sk_dict* d, sk_string key) {
    if (!d || key.__is_null || d->capacity == 0) return any_null();
    unsigned int h = __sk__dict_hash(key.value);
    int slot = __sk__dict_find(d, key.value, h);
    if (d->entries[slot].key == NULL) return any_null();
    return d->entries[slot].value;
}

int sk_dict_has(sk_dict* d, sk_string key) {
    if (!d || key.__is_null || d->capacity == 0) return 0;
    unsigned int h = __sk__dict_hash(key.value);
    int slot = __sk__dict_find(d, key.value, h);
    return d->entries[slot].key != NULL;
}

int sk_dict_len(sk_dict* d) { return d ? d->length : 0; }

void sk_dict_free(sk_dict* d) {
    if (!d) return;
    for (int i = 0; i < d->capacity; i++) {
        if (d->entries[i].key != NULL) {
            free(d->entries[i].key);
            sk_any_deep_free(&d->entries[i].value);
        }
    }
    if (d->entries) free(d->entries);
    free(d);
}

sk_dict_ref sk_dict_ref_new(sk_dict* d) {
    sk_dict_ref r; r.value = d; r.__is_null = d ? 0 : 1; return r;
}

sk_dict* sk_dict_deep_copy(sk_dict* d) {
    if (!d) return NULL;
    sk_dict* copy = sk_dict_new();
    for (int i = 0; i < d->capacity; i++) {
        if (d->entries[i].key != NULL) {
            sk_string k = sk_string_new(d->entries[i].key);
            sk_any v = sk_any_deep_copy(d->entries[i].value);
            sk_dict_set(copy, k, v);
        }
    }
    return copy;
}

void sk_dict_deep_free(sk_dict* d) { sk_dict_free(d); }

sk_any any_null(void) { sk_any a; a.type = 6; a.prec = -1; a.data.p = NULL; return a; }
sk_any any_int(sk_int v) { sk_any a; if (v.__is_null) { a.type = 6; a.prec = -1; a.data.p = NULL; return a; } a.type = 0; a.prec = -1; a.data.i = v.value; return a; }
sk_any any_string(sk_string v) { sk_any a; if (v.__is_null) { a.type = 6; a.prec = -1; a.data.p = NULL; return a; } a.type = 1; a.prec = -1; a.data.s = v.value ? strdup(v.value) : NULL; return a; }
sk_any any_float(sk_float v) { sk_any a; if (v.__is_null) { a.type = 6; a.prec = -1; a.data.p = NULL; return a; } a.type = 2; a.prec = v.prec; a.data.f = v.value; return a; }
sk_any any_double(sk_double v) { sk_any a; if (v.__is_null) { a.type = 6; a.prec = -1; a.data.p = NULL; return a; } a.type = 3; a.prec = v.prec; a.data.d = v.value; return a; }
sk_any any_bool(sk_bool v) { sk_any a; if (v.__is_null) { a.type = 6; a.prec = -1; a.data.p = NULL; return a; } a.type = 4; a.prec = -1; a.data.b = v.value; return a; }
sk_any any_char(sk_char v) { sk_any a; a.type = 7; a.prec = -1; a.data.i = v; return a; }
sk_any any_arr(sk_arr v) { sk_any a; if (v.__is_null) { a.type = 6; a.prec = -1; a.data.p = NULL; return a; } a.type = 5; a.prec = -1; a.data.p = v.value ? sk_array_deep_copy(v.value) : NULL; return a; }
sk_any any_dict(sk_dict_ref v) { sk_any a; if (v.__is_null) { a.type = 6; a.prec = -1; a.data.p = NULL; return a; } a.type = 8; a.prec = -1; a.data.p = v.value; return a; }

sk_any sk_any_deep_copy(sk_any a) {
    sk_any r = a;
    switch (a.type) {
        case 1: // string
            r.data.s = a.data.s ? strdup(a.data.s) : NULL;
            break;
        case 5: // arr
            r.data.p = a.data.p ? sk_array_deep_copy((sk_array*)a.data.p) : NULL;
            break;
        case 8: // dict
            r.data.p = a.data.p ? sk_dict_deep_copy((sk_dict*)a.data.p) : NULL;
            break;
        default:
            break;
    }
    return r;
}

void sk_any_deep_free(sk_any* a) {
    if (!a) return;
    switch (a->type) {
        case 1: // string
            if (a->data.s) { free(a->data.s); a->data.s = NULL; }
            break;
        case 5: // arr
            if (a->data.p) { sk_array_deep_free((sk_array*)a->data.p); a->data.p = NULL; }
            break;
        case 8: // dict
            if (a->data.p) { sk_dict_deep_free((sk_dict*)a->data.p); a->data.p = NULL; }
            break;
        default:
            break;
    }
    a->type = -1;
}

sk_int any_to_int(sk_any a) {
    if (a.type == 6) return SK_NULL_int;
    switch (a.type) {
        case 0: return sk_int_new(a.data.i);
        case 1: return sk_int_new(atoi(a.data.s));
        case 2: return sk_int_new((int)a.data.f);
        case 3: return sk_int_new((int)a.data.d);
        case 4: return sk_int_new(a.data.b ? 1 : 0);
        case 7: return sk_int_new(a.data.i);
        default: return SK_NULL_int;
    }
}
sk_char any_to_char(sk_any a) {
    if (a.type == 7) return (sk_char)a.data.i;
    if (a.type == 0) return (sk_char)a.data.i;
    return 0;
}
sk_float any_to_float(sk_any a) {
    if (a.type == 6) return SK_NULL_float;
    sk_float r;
    switch (a.type) {
        case 0: r = sk_float_new((float)a.data.i); break;
        case 1: r = sk_float_new((float)atof(a.data.s)); break;
        case 2: r = sk_float_new(a.data.f); break;
        case 3: r = sk_float_new((float)a.data.d); break;
        case 4: r = sk_float_new(a.data.b ? 1.0f : 0.0f); break;
        default: return SK_NULL_float;
    }
    if (a.prec >= 0) r.prec = a.prec;
    return r;
}
sk_double any_to_double(sk_any a) {
    if (a.type == 6) return SK_NULL_double;
    sk_double r;
    switch (a.type) {
        case 0: r = sk_double_new((double)a.data.i); break;
        case 1: r = sk_double_new(atof(a.data.s)); break;
        case 2: r = sk_double_new((double)a.data.f); break;
        case 3: r = sk_double_new(a.data.d); break;
        case 4: r = sk_double_new(a.data.b ? 1.0 : 0.0); break;
        default: return SK_NULL_double;
    }
    if (a.prec >= 0) r.prec = a.prec;
    return r;
}
sk_bool any_to_bool(sk_any a) {
    if (a.type == 6) return SK_NULL_bool;
    switch (a.type) {
        case 0: return sk_bool_new(a.data.i != 0);
        case 1: return sk_bool_new(a.data.s[0] != '\0');
        case 2: return sk_bool_new(a.data.f != 0.0f);
        case 3: return sk_bool_new(a.data.d != 0.0);
        case 4: return sk_bool_new(a.data.b);
        default: return SK_NULL_bool;
    }
}
sk_string any_to_string(sk_any a) {
    if (a.type == 6) return sk_string_new("null");
    char buf[64];
    switch (a.type) {
        case 0: snprintf(buf, 64, "%d", a.data.i); return sk_string_new(buf);
        case 1: return sk_string_new(a.data.s);
        case 2: if (a.prec >= 0) snprintf(buf, 64, "%.*f", a.prec, a.data.f); else snprintf(buf, 64, "%f", a.data.f); return sk_string_new(buf);
        case 3: if (a.prec >= 0) snprintf(buf, 64, "%.*f", a.prec, a.data.d); else snprintf(buf, 64, "%f", a.data.d); return sk_string_new(buf);
        case 4: return sk_string_new(a.data.b ? "true" : "false");
        case 5: return sk_array_to_string((sk_array*)a.data.p);
        case 7: return sk_char_to_string((sk_char)a.data.i);
        case 8: {
            sk_dict* d = (sk_dict*)a.data.p;
            size_t cap = 256; size_t blen = 0;
            char* buf = malloc(cap);
            buf[0] = '\0';
            #define SK_D_APP(s) do { \
                size_t sl = strlen(s); \
                while (blen + sl + 2 > cap) { cap *= 2; buf = realloc(buf, cap); } \
                memcpy(buf + blen, s, sl); blen += sl; buf[blen] = '\0'; \
            } while (0)
            SK_D_APP("{");
            int first = 1;
            for (int i = 0; i < d->capacity; i++) {
                if (d->entries[i].key == NULL) continue;
                if (!first) SK_D_APP(", ");
                first = 0;
                SK_D_APP(d->entries[i].key);
                SK_D_APP(": ");
                sk_string vs = any_to_string(d->entries[i].value);
                SK_D_APP(vs.value);
                free(vs.value);
            }
            SK_D_APP("}");
            #undef SK_D_APP
            return sk_string_new_take(buf);
        }
        default: return sk_string_new("unknown");
    }
}
sk_arr any_to_arr(sk_any a) {
    if (a.type == 6) return SK_NULL_arr;
    if (a.type == 5) return sk_arr_new(sk_array_deep_copy((sk_array*)a.data.p));
    return SK_NULL_arr;
}
sk_dict_ref any_to_dict(sk_any a) {
    if (a.type == 8) return sk_dict_ref_new((sk_dict*)a.data.p);
    return SK_NULL_dict;
}

