typedef struct SkCleanup {
    void** ptr;
    int type;
    struct SkCleanup* next;
} SkCleanup;

typedef struct SkTryFrame {
    jmp_buf env;
    void* error;
    struct SkTryFrame* prev;
    SkCleanup* cleanup;
} SkTryFrame;

SkTryFrame* sk_try_stack = NULL;

void sk_any_free(sk_any* a) {
    if (a->type == 1 && a->data.s) { free(a->data.s); a->data.s = NULL; }
    else if (a->type == 5 && a->data.p) { sk_array_deep_free((sk_array*)a->data.p); a->data.p = NULL; }
    a->type = -1;
}

void sk_try_register(void** ptr, int type) {
    if (sk_try_stack == NULL) return;
    SkCleanup* c = malloc(sizeof(SkCleanup));
    c->ptr = ptr;
    c->type = type;
    c->next = sk_try_stack->cleanup;
    sk_try_stack->cleanup = c;
}

void sk_try_cleanup(SkTryFrame* frame) {
    SkCleanup* c = frame->cleanup;
    while (c) {
        if (*c->ptr != NULL) {
            switch (c->type) {
                case 0: free(*c->ptr); break;
                case 1: sk_array_free(*(sk_array**)c->ptr); break;
                case 2: sk_any_free((sk_any*)c->ptr); break;
            }
            *c->ptr = NULL;
        }
        SkCleanup* next = c->next;
        free(c);
        c = next;
    }
    frame->cleanup = NULL;
}

void sk_try_push(SkTryFrame* frame) {
    frame->prev = sk_try_stack;
    frame->cleanup = NULL;
    frame->error = NULL;
    sk_try_stack = frame;
}

void sk_try_pop(SkTryFrame* frame) {
    SkCleanup* c = frame->cleanup;
    while (c) {
        SkCleanup* next = c->next;
        free(c);
        c = next;
    }
    frame->cleanup = NULL;
    sk_try_stack = frame->prev;
}

void sk_error_free(void* err) {
    if (!err) return;
    sk_string* msg = (sk_string*)((char*)err + sizeof(const char*));
    if (msg->value) { free(msg->value); msg->value = NULL; }
    free(err);
}

void sk_throw(void* err, const char* file, int line, int col) {
    if (sk_try_stack == NULL) {
        const char* __type = *(const char**)err;
        if (sk_call_stack_top > 0) {
            SkCallFrame* top = &sk_call_stack[sk_call_stack_top - 1];
            fprintf(stderr, "Panicked with error (%s) at %s:%d:%d (thrown from %s:%d:%d)\n",
                __type, top->file, top->line, top->col, file, line, col);
        } else {
            fprintf(stderr, "Panicked with error (%s) at %s:%d:%d\n", __type, file, line, col);
        }
        exit(1);
    }
    SkTryFrame* frame = sk_try_stack;
    while (frame != NULL) {
        sk_try_cleanup(frame);
        frame = frame->prev;
    }
    sk_try_stack->error = err;
    longjmp(sk_try_stack->env, 1);
}

int sk_error_type_match(const char* actual, const char* expected) {
    size_t len = strlen(expected);
    if (strncmp(actual, expected, len) != 0) return 0;
    return actual[len] == '\0' || actual[len] == '.';
}

// ==== Async / Promise runtime ====
typedef struct {
    _Atomic int owner_ref;
    _Atomic int task_ref;
    _Atomic int done;
    pthread_mutex_t mtx;
    pthread_cond_t cv;
} sk_promise_common;

static inline void sk_promise_common_destroy(sk_promise_common* c) {
    pthread_mutex_destroy(&c->mtx);
    pthread_cond_destroy(&c->cv);
}

typedef struct {
    sk_promise_common common;
    void* error;
} sk_promise_void;

static inline sk_promise_void* sk_promise_new_void(void) {
    sk_promise_void* p = malloc(sizeof(sk_promise_void));
    atomic_store(&p->common.owner_ref, 1);
    atomic_store(&p->common.task_ref, 1);
    atomic_store(&p->common.done, 0);
    pthread_mutex_init(&p->common.mtx, NULL);
    pthread_cond_init(&p->common.cv, NULL);
    p->error = NULL;
    return p;
}

static inline void sk_promise_finish_void(sk_promise_void* p) {
    pthread_mutex_lock(&p->common.mtx);
    atomic_store(&p->common.done, 1);
    pthread_cond_broadcast(&p->common.cv);
    pthread_mutex_unlock(&p->common.mtx);
}

static inline void sk_promise_await_void(sk_promise_void* p) {
    pthread_mutex_lock(&p->common.mtx);
    while (!atomic_load(&p->common.done)) {
        pthread_cond_wait(&p->common.cv, &p->common.mtx);
    }
    if (p->error) {
        void* err = p->error;
        p->error = NULL;
        pthread_mutex_unlock(&p->common.mtx);
        sk_throw(err, "<await>", 0, 0);
    }
    pthread_mutex_unlock(&p->common.mtx);
}

static inline void sk_promise_fail_void(sk_promise_void* p, void* err) {
    pthread_mutex_lock(&p->common.mtx);
    p->error = err;
    atomic_store(&p->common.done, 1);
    pthread_cond_broadcast(&p->common.cv);
    pthread_mutex_unlock(&p->common.mtx);
}

static inline sk_bool sk_promise_ended_void(sk_promise_void* p) {
    sk_bool r; r.value = atomic_load(&p->common.done) ? 1 : 0; r.__is_null = 0; return r;
}

static inline void sk_promise_release_void(sk_promise_void* p) {
    if (!p) return;
    atomic_fetch_sub(&p->common.owner_ref, 1);
    if (atomic_load(&p->common.owner_ref) == 0 && atomic_load(&p->common.task_ref) == 0) {
        sk_promise_common_destroy(&p->common);
        free(p);
    }
}

